function initials(name:string){return name.trim().split(/\s+/).slice(0,2).map(n=>n[0]).join('').toUpperCase()||'?';}
async function imageDataUrl(file:File){const prepared=await preparePhoto(file);return await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>typeof reader.result==='string'?resolve(reader.result):reject(new Error('This company logo could not be read.'));reader.onerror=()=>reject(new Error('This company logo could not be read.'));reader.readAsDataURL(prepared);});}
function color(name:string){return ['','blue','rose','gold'][Array.from(name).reduce((a,c)=>a+c.charCodeAt(0),0)%4];}
function Avatar({name,small=false,photo}:{name:string;small?:boolean;photo?:string}){return <span className={'avatar '+color(name)+(small?' small':'')} aria-hidden="true">{photo?<img src={photo} alt=""/>:initials(name)}</span>;}
function roomName(room:Room,state:ChatState){if(room.kind!=='dm')return room.name;return state.members.find(m=>room.memberIds.includes(m.id)&&m.id!==state.me.id)?.name||'Former member';}
function time(at:number){return new Date(at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});}
function date(at:number){return new Date(at).toLocaleDateString([],{month:'short',day:'numeric',year:'numeric'});}
function day(at:number){const d=new Date(at),now=new Date();return d.toDateString()===now.toDateString()?'Today':d.toLocaleDateString([],{weekday:'long',month:'long',day:'numeric'});}
function TextBody({body}:{body:string}){return <>{body.split(/(https?:\/\/[^\s<>]+)/g).map((part,i)=>/^https?:\/\//.test(part)?<a key={i} href={part} target="_blank" rel="noopener noreferrer">{part}</a>:part)}</>;}
type PageData={messages:Message[];parent:Message|null;hasMore:boolean;serverTime:number};
type Confirm={title:string;description:string;label:string;run:()=>Promise<unknown>};
type Draft={body:string;files:File[];nonce:string;busy:boolean;pending:boolean;preparing:boolean;error:string;sent?:boolean};
