export default function ChatApp(){
  useEffect(()=>{if('serviceWorker' in navigator&&window.isSecureContext)void navigator.serviceWorker.register('/sw.js',{scope:'/',updateViaCache:'none'}).catch(()=>{});},[]);
  const page=window.location.pathname.replace(/\/$/,'');
  if(page==='/billing'&&clientCompany()==='main')return <CrewBillingRedirect/>;
  if(page==='/billing')return <AccessGate>{(initial)=>initial.me.role==='owner'?<BillingPage initial={initial}/>:<p>Owner access required.</p>}</AccessGate>;
  if(page==='/signup')return <PublicSignup/>;
  if(page==='/platform-admin')return <AccessGate>{initial=>initial.me.role==='owner'&&clientCompany()==='main'?<PlatformAdmin/>:<main className="company-admin-page"><h1>Platform administration is private</h1><a href={companyUrl('/')}>Back to Chat</a></main>}</AccessGate>;
  if(window.location.pathname.replace(/\/$/,'')==='/company-admin')return <AccessGate>{(initial,onSignOut)=>initial.me.role==='owner'&&initial.companyReady===false?<CompanyOnboarding/>:<CompanyAdmin initial={initial} onSignOut={onSignOut}/>}</AccessGate>;
  return <AccessGate>{(initial,onSignOut,onSessionLost)=>initial.me.role==='owner'&&initial.companyReady===false?<CompanyOnboarding/>:clientCompany()!=='main'&&initial.billingRequired?(initial.me.role==='owner'?<BillingPage initial={initial}/>:<main className="company-admin-page"><h1>Company subscription needs attention</h1><p>Ask your company owner to update billing. Your saved information is retained.</p><button onClick={onSignOut}>Log out</button></main>):initial.products?.chat===false?<ProductOnlyHome initial={initial} onSignOut={onSignOut}/>:<SidebarProvider className="app-shell" style={{'--sidebar-width':'260px'} as CSSProperties}><Workspace key={initial.me.id} initial={initial} onSignOut={onSignOut} onSessionLost={onSessionLost}/><Toaster theme="light" position="top-center" richColors/></SidebarProvider>}</AccessGate>;
}

